    "/api/v1/queue/today": {
      get: {
        tags: ["Queue"],
        summary: "\u0639\u0631\u0636 \u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0627\u0646\u062A\u0638\u0627\u0631 \u0648\u0635\u0627\u0644\u0629 \u0627\u0644\u0643\u0634\u0641 \u0644\u0644\u064A\u0648\u0645 \u0627\u0644\u062D\u0627\u0644\u064A \u0644\u0643\u0627\u0641\u0629 \u0623\u0637\u0628\u0627\u0621 \u0627\u0644\u0639\u064A\u0627\u062F\u0629 (\u0623\u0648 \u0644\u0637\u0628\u064A\u0628 \u0645\u062D\u062F\u062F)",
        security: [{ BearerAuth: [] }],
        parameters: [
          {
            name: "doctorId",
            in: "query",
            schema: { type: "string" },
            description: "\u0645\u0639\u0631\u0641 \u0627\u0644\u0637\u0628\u064A\u0628 (\u0627\u062E\u062A\u064A\u0627\u0631\u064A - \u0641\u064A \u062D\u0627\u0644 \u0639\u062F\u0645 \u062A\u0645\u0631\u064A\u0631\u0647 \u064A\u062A\u0645 \u062C\u0644\u0628 \u0637\u0627\u0628\u0648\u0631 \u062C\u0645\u064A\u0639 \u0623\u0637\u0628\u0627\u0621 \u0627\u0644\u0639\u064A\u0627\u062F\u0629 \u062F\u0641\u0639\u0629 \u0648\u0627\u062D\u062F\u0629 \u0644\u0645\u0648\u0638\u0641 \u0627\u0644\u0627\u0633\u062A\u0642\u0628\u0627\u0644)"
          }
        ],
        responses: {
          200: {
            description: "\u0637\u0627\u0628\u0648\u0631 \u0627\u0644\u064A\u0648\u0645 \u0648\u062D\u0627\u0644\u0627\u062A \u0627\u0644\u0645\u0631\u0636\u0649 \u0627\u0644\u062D\u0627\u0644\u064A\u0629",
            content: {
              "application/json": {
                schema: {
                  type: "object",
                  properties: {
                    status: { type: "boolean", example: true },
                    code: { type: "integer", example: 200 },
                    payload: {
                      type: "object",
                      properties: {
                        waiting: { type: "array", items: { $ref: "#/components/schemas/AppointmentDto" } },
                        inProgress: { $ref: "#/components/schemas/AppointmentDto" },
                        completedCount: { type: "integer", example: 12 }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
